) AS v(
  id text,
  set_title boolean, title text, old_title_md5 text,
  set_hares boolean, hares text, old_hares_md5 text,
  set_run boolean, run_number integer, old_run integer,
  set_desc boolean, description text, old_desc_md5 text,
  set_loc boolean, location text, old_loc_md5 text
)
WHERE e."id" = v.id
  AND (v.set_title IS NOT TRUE OR md5(e."title") = v.old_title_md5)
  AND (v.set_hares IS NOT TRUE OR md5(e."haresText") IS NOT DISTINCT FROM v.old_hares_md5)
  AND (v.set_run   IS NOT TRUE OR e."runNumber" IS NOT DISTINCT FROM v.old_run)
  AND (v.set_desc  IS NOT TRUE OR md5(e."description") IS NOT DISTINCT FROM v.old_desc_md5)
  AND (v.set_loc   IS NOT TRUE OR md5(e."locationName") IS NOT DISTINCT FROM v.old_loc_md5);
